import { useState, useEffect } from 'react';
import { HiMenuAlt3, HiX } from 'react-icons/hi';

function Navbar() {
    const [showMenu, setShowMenu] = useState(false);

    const scrollToComponent = (componentId) => {
        const component = document.getElementById(componentId);
        if (component) {
            component.scrollIntoView({
                behavior: 'smooth',
                duration: 2000,
                block: 'start',
                inline: 'nearest',
            });
            setShowMenu(false); // Close mobile menu after clicking
        }
    };

    const handleWindowResize = () => {
        const screenWidth = window.innerWidth;
        if (screenWidth > 768 && showMenu) {
            setShowMenu(false);
        }
    };

    useEffect(() => {
        window.addEventListener('resize', handleWindowResize);
        return () => {
            window.removeEventListener('resize', handleWindowResize);
        };
    }, [showMenu]);


    return (
        <nav className="sticky top-0 z-50 bg-[#20262E]/90 backdrop-blur-sm border-b border-gray-700/50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex justify-between items-center py-4">
                    {/* Logo/Brand */}
                    <div className="text-2xl font-bold text-white">
                        <span className="text-[#6699CC]">Portfolio</span>
                    </div>

                    {/* Desktop Menu */}
                    <ul className="hidden md:flex items-center space-x-8 font-medium text-white">
                        <li>
                            <a
                                className="tracking-wider cursor-pointer hover:text-[#6699CC] transition-colors duration-300 relative group"
                                onClick={() => scrollToComponent('experience')}
                            >
                                Experience
                                <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-[#6699CC] group-hover:w-full transition-all duration-300"></span>
                            </a>
                        </li>
                        <li>
                            <a
                                className="tracking-wider cursor-pointer hover:text-[#6699CC] transition-colors duration-300 relative group"
                                onClick={() => scrollToComponent('skills')}
                            >
                                Skills
                                <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-[#6699CC] group-hover:w-full transition-all duration-300"></span>
                            </a>
                        </li>
                        <li>
                            <a
                                className="tracking-wider cursor-pointer hover:text-[#6699CC] transition-colors duration-300 relative group"
                                onClick={() => scrollToComponent('projects')}
                            >
                                Projects
                                <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-[#6699CC] group-hover:w-full transition-all duration-300"></span>
                            </a>
                        </li>
                    </ul>

                    {/* Mobile Menu Button */}
                    <button
                        className="md:hidden text-white hover:text-[#6699CC] transition-colors duration-300"
                        onClick={() => setShowMenu(!showMenu)}
                    >
                        {showMenu ? <HiX size={28} /> : <HiMenuAlt3 size={28} />}
                    </button>
                </div>

                {/* Mobile Menu */}
                {showMenu && (
                    <div className="md:hidden bg-[#20262E] border-t border-gray-700/50">
                        <ul className="py-4 space-y-4">
                            <li>
                                <a
                                    className="block px-4 py-2 text-white hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer"
                                    onClick={() => scrollToComponent('experience')}
                                >
                                    Experience
                                </a>
                            </li>
                            <li>
                                <a
                                    className="block px-4 py-2 text-white hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer"
                                    onClick={() => scrollToComponent('skills')}
                                >
                                    Skills
                                </a>
                            </li>
                            <li>
                                <a
                                    className="block px-4 py-2 text-white hover:text-[#6699CC] hover:bg-gray-700/30 transition-all duration-300 cursor-pointer"
                                    onClick={() => scrollToComponent('projects')}
                                >
                                    Projects
                                </a>
                            </li>
                        </ul>
                    </div>
                )}
            </div>
        </nav>
    );
}

export default Navbar;
